fun networkDate(done:(String?)->Unit){Thread{val result=runCatching{val con=(URL("https://www.google.com/generate_204").openConnection() as HttpURLConnection);con.requestMethod="HEAD";con.connectTimeout=5000;con.readTimeout=5000;con.connect();val ms=con.date;con.disconnect();if(ms<=0)error("no date");Instant.ofEpochMilli(ms).atZone(ZoneId.systemDefault()).toLocalDate().toString()}.getOrNull();Handler(Looper.getMainLooper()).post{done(result)}}.start()}
